#include "dsky_nv_blank_check.h"
#include "dsky_nv_blank_vectors.h"
uint8_t dsky_nv_blank_checkpoint_input(uint8_t n,apollo_overlay_state *s,p66_bias_io *io,agc_word *channel11,enum dsky_nv_mission *mission){if(n>=128u)return 0;dsky_nv_blank_input(s,io,channel11,dsky_nv_blank_numbers[n],mission);return 1;}
uint16_t dsky_nv_blank_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;agc_word channel11,oldchannel;enum dsky_nv_mission mission;uint16_t f,p,end,failures=0;if(!dsky_nv_blank_checkpoint_input(n,s,&io,&channel11,&mission))return 1;*before=*s;old=io;oldchannel=channel11;if(dsky_nv_blank(s,&io,&channel11,mission)!=P66_BIAS_OK)++failures;p=dsky_nv_blank_after_offsets[n];end=dsky_nv_blank_after_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:oldchannel;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:channel11;if(p<end&&dsky_nv_blank_after_patch[p][0]==f)expected=dsky_nv_blank_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
